Definition budget_chk (c : Z) : bool := (size_of_class c * (HB / mth c + 4) <=? 2^28) && (6 <=? mth c) && (0 <=? size_of_class c).
Lemma budget_chk_range : forallb budget_chk (zseq 3 (Z.to_nat 29)) = true.
Proof.
