Lemma room_of_AINV : forall pc pb st c,
  AINV ATOP pc pb st -> 1 <= c <= 31 -> size_of_class c <= 65536 -> 0 <= size_of_class c ->
  bsum (qbatches pb st) <= 2^28 + 2^22 -> size_of_class c * cntP c pc <= 2^20 ->
