Lemma CH_bounds_gen : forall pc pb st QB,
  AINV ATOP pc pb st -> bsum (qbatches pb st) <= QB -> 0 <= QB <= 2^31 -> zlen (secs pc) <= 2 -> secbytes pc <= 2^31 ->
